mapper.select:
select A.id ,A.pw ,A.name ,A.email ,A.phone ,A.gender ,A.hobby
,regexp_substr(a.phone, '[^-]+', 1, 1) as phone1 ,regexp_substr(a.phone, '[^-]+', 1, 2) as phone2 ,regexp_substr(a.phone, '[^-]+', 1, 3) as phone3 ,regexp_substr(a.email, '[^@]+', 1, 1) as email_id ,regexp_substr(a.email, '[^@]+', 1, 2) as email_domain from member A where 1=1
and A.id = #{id}
